 for(unsigned int i=0;i<source.scene.nodeCount;i++){const WorldText::SceneNode& n=source.scene.nodes[i];if(n.kind!=1)continue;if(FearBrushFlags::Equal(n.type,"ExtrudeSector")||FearBrushFlags::Equal(n.type,"SemiExtrudeSector"))ExitProcess(4);if(FearBrushFlags::Equal(n.type,"Sector"))count++;}
 if(!count||count>5000)ExitProcess(5);PrefabScene::Arena memory;StreamingSplit::Bounds* bounds=(StreamingSplit::Bounds*)memory.Allocate(count*sizeof(StreamingSplit::Bounds));const char** names=(const char**)memory.Allocate(count*sizeof(char*));SectorPortals::PreparedSector* sectors=(SectorPortals::PreparedSector*)memory.Allocate(count*sizeof(SectorPortals::PreparedSector));if(!bounds||!names||!sectors)ExitProcess(6);unsigned int index=0;
